"""The officer's queue -- the demo UI.

RUNTIME. Run with::

    streamlit run app/streamlit_app.py

**This is the officer's view, not a chatbot.** The human queue is where a reviewer
actually works, so the screen is organised around the two things they do: confirm
what was automated, and act on what was not. An escalated item is therefore not a
failure state to be hidden -- it is the primary content (``BUILD.md`` S5.9).

Three commitments the layout makes good on:

* **Every escalated item carries a reason chip.** An officer sorting a queue needs
  to know why an item is in front of them before they open it, and the reason is
  closed vocabulary rather than free text, so the queue can be grouped by it.
* **The SOP pane renders the retrieved procedure in full.** This is what makes a
  drafting failure workable rather than dead: the officer writes the reply from the
  same source the drafter would have used.
* **Drafts are live.** Free-tier rate limits are visible here rather than hidden --
  a rate-limited item shows its failure reason and its SOP, which is the designed
  behaviour and not a defect to apologise for.

The risk-coverage slider re-routes already-classified items through the REAL router
at a new threshold multiplier. Nothing is re-classified, so the slider is instant
and the curve it traces is the one the system would actually follow.
"""

from __future__ import annotations

import html
import json
import sys
from pathlib import Path
from typing import Any

import streamlit as st

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "src"))
sys.path.insert(0, str(ROOT))

from triage.env import load_env  # noqa: E402

load_env()

from eval.dataset import split  # noqa: E402

from triage.graph import build_default_deps, build_graph, run_one  # noqa: E402
from triage.models.calibration import TemperatureScaler  # noqa: E402
from triage.models.encoder import ModelNotTrainedError  # noqa: E402
from triage.nodes.calibrate import calibrate, rollup  # noqa: E402
from triage.nodes.flags import detect_flags  # noqa: E402
from triage.nodes.route import load_thresholds, route  # noqa: E402
from triage.pii.scrubber import Scrubber  # noqa: E402
from triage.schemas import Action, DraftStatus, TriageState  # noqa: E402
from triage.sop.index import build_index  # noqa: E402

RESULTS = ROOT / "eval" / "results"

st.set_page_config(
    page_title="Citizen triage â€” officer queue",
    layout="wide",
    initial_sidebar_state="expanded",
)

#: Queue styling. Density is the point: an officer sorting a queue wants many items
#: on screen at once, and the default Streamlit button is tall, centred and heavy.
#: These rules restyle the row buttons into flush-left list rows -- borderless, tight
#: leading, a hairline between them -- so roughly three times as many items are
#: visible without changing what a row says.
#:
#: Colour is carried by the chips rather than the rows: an escalated item is already
#: distinguished by sitting in the review queue, so tinting whole rows would spend
#: the screen's only strong colour on a distinction the tab already makes. All
#: colours are set against both themes, since a fixed palette would invert badly
#: for anyone running Streamlit in dark mode.
#: The row hook is Streamlit's own ``st-key-<key>`` class, which it stamps on the
#: element container for any keyed widget. That is a documented, stable handle;
#: matching on emotion hashes or on sibling position would break on a version bump.
#: Row keys are prefixed ``qrow-``, so these rules touch the queue and nothing else.
_QUEUE_CSS = """
<style>
/* The queue rows. Streamlit renders each as a button; these strip the button
   chrome and leave a flush-left list row. */
div[class*="st-key-qrow-"] button {
    text-align: left !important;
    justify-content: flex-start !important;
    align-items: flex-start !important;
    padding: 5px 10px !important;
    margin: 0 !important;
    border: none !important;
    border-bottom: 1px solid rgba(128, 128, 128, 0.18) !important;
    border-radius: 0 !important;
    background: transparent !important;
    font-weight: 400 !important;
    line-height: 1.3 !important;
    min-height: 0 !important;
    height: auto !important;
}
div[class*="st-key-qrow-"] button:hover {
    background: rgba(128, 128, 128, 0.12) !important;
}
div[class*="st-key-qrow-"] button:focus {
    box-shadow: none !important;
    outline: none !important;
}
/* Collapse the gap Streamlit reserves between stacked widgets so rows sit flush. */
div[class*="st-key-qrow-"] { margin-top: -0.75rem !important; }

/* Streamlit centres a button's label with FLEXBOX, not text-align, and it does so
   on two unnamed wrappers between the button and the markdown -- a div and a span,
   both ``justify-content: center``. Overriding text-align alone leaves the label
   centred; these have to be reset to flex-start and given the full width, or they
   shrink-wrap and re-centre. */
div[class*="st-key-qrow-"] button > div,
div[class*="st-key-qrow-"] button > div > span {
    justify-content: flex-start !important;
    align-items: flex-start !important;
    width: 100% !important;
}
div[class*="st-key-qrow-"] button div[data-testid="stMarkdownContainer"] {
    width: 100% !important;
    text-align: left !important;
}

/* Line one is the subject (bold, slightly larger), line two the status and
   sender. Both live in ONE markdown paragraph separated by a hard break, so the
   status line is coloured through Streamlit's own ``:orange[...]`` markdown in
   the label rather than from here -- a <br>-separated line cannot be selected in
   CSS. */
div[class*="st-key-qrow-"] button p {
    margin: 0 !important;
    padding-left: 0 !important;
    text-indent: 0 !important;
    text-align: left !important;
    width: 100% !important;
    font-size: 0.78rem !important;
    line-height: 1.35 !important;
}
div[class*="st-key-qrow-"] button p strong { font-size: 0.84rem; font-weight: 600; }

/* The selected row: a left rule and a tint, so the list echoes what the detail
   pane is showing. Without this, selection lived only in session_state and the
   queue gave no sign of which item was open. */
div[class*="st-key-qrow-sel-"] button {
    background: rgba(56, 122, 223, 0.16) !important;
    box-shadow: inset 3px 0 0 0 #387adf !important;
}
div[class*="st-key-qrow-sel-"] button p { font-weight: 600 !important; }

/* The metric strip: smaller, so it reads as a status bar rather than a dashboard.
   The contribution is the queue and the curve, not these summary numbers. */
div[data-testid="stMetricValue"] { font-size: 1.45rem !important; }
div[data-testid="stMetricLabel"] { font-size: 0.75rem !important; opacity: 0.75; }

/* Tighten the top padding Streamlit reserves above the title. */
div.block-container { padding-top: 2.6rem !important; }
</style>
"""
st.markdown(_QUEUE_CSS, unsafe_allow_html=True)


# --------------------------------------------------------------------------- #
# Loading. Cached, because the corpus and the weights load once per session.
# --------------------------------------------------------------------------- #


@st.cache_resource
def _index() -> Any:
    return build_index()


@st.cache_resource
def _scrubber() -> Scrubber:
    return Scrubber()


@st.cache_resource
def _classifier() -> Any:
    """The fine-tuned encoder. Absent weights are a message, not a traceback."""
    from triage.models.encoder import EncoderClassifier

    return EncoderClassifier()


@st.cache_data(show_spinner="Classifying the inbox â€¦")
def _triage(split_name: str, limit: int) -> list[dict[str, Any]]:
    """Scrub, classify, roll up and calibrate every email ONCE.

    Routing is deliberately left out: the slider re-routes these rows without
    re-classifying, which is what keeps it interactive and what guarantees the
    displayed decision comes from the real router rather than a copy of its rule.
    """
    index, scrubber, classifier = _index(), _scrubber(), _classifier()
    scaler = TemperatureScaler.load()
    bucket_of = dict(index.bucket)

    rows: list[dict[str, Any]] = []
    items = split(split_name)[:limit]
    scrubs = [scrubber.scrub(item.email.text) for item in items]
    classifications = classifier.predict_batch([s.text for s in scrubs])
    for item, scrub, classification in zip(items, scrubs, classifications, strict=True):
        bucket, summed = rollup(classification, bucket_of)
        score = calibrate(bucket, summed, scaler)
        rows.append({
            "id": item.email.id,
            "subject": item.email.subject or "(no subject)",
            "sender": item.email.sender or "unknown sender",
            "received_at": item.email.received_at,
            "body": scrub.text,
            "truth": item.label,
            "predicted": classification.label,
            "score": score,
            "flags": detect_flags(scrub.text, classification),
            "sop_ids": tuple(s.sop_id for s in index.sops_for(classification.label)),
        })
    return rows


@st.cache_resource
def _graph(multiplier: float) -> Any:
    """The compiled graph, built once per threshold multiplier.

    Rebuilding it per draft re-read the SOP corpus, re-loaded the temperature and
    re-constructed the Gemini client on every click; the deps exist to be resolved
    once at startup (``graph.py``), so caching here restores that.
    """
    return build_graph(
        build_default_deps(classifier=_classifier(), multiplier=multiplier)
    )


def _email_for(split_name: str, email_id: str) -> Any:
    """Look the email up by id rather than by position.

    Positional lookup indexed the FULL split with an offset computed inside the
    truncated ``rows`` list. They agree only while ``rows`` is an unfiltered prefix,
    so any future sort or filter of the queue would have drafted a reply to the
    wrong citizen's email -- silently, since both are valid emails.
    """
    for item in split(split_name):
        if item.email.id == email_id:
            return item.email
    raise KeyError(f"no email {email_id!r} in split {split_name!r}")


@st.cache_data
def _risk_coverage() -> dict[str, Any] | None:
    path = RESULTS / "risk_coverage.json"
    if not path.exists():
        return None
    return json.loads(path.read_text(encoding="utf-8"))


def _draft_run_key(split_name: str, email_id: str, multiplier: float) -> str:
    """Identify a live drafting attempt at one routing operating point."""
    return f"{split_name}:{email_id}:{multiplier:.2f}"


def _draft_runs() -> dict[str, TriageState]:
    """Live results retained for the session so reruns never repeat an API call."""
    if "draft_runs" not in st.session_state:
        st.session_state["draft_runs"] = {}
    return st.session_state["draft_runs"]


def _in_human_queue(decision: Any, run: TriageState | None) -> bool:
    """Use the completed graph state once drafting has been attempted."""
    if run is not None:
        return run.in_human_queue
    return not decision.is_automated


def _markdown_inline(value: Any) -> str:
    """Render an untrusted value as one inert line inside a Markdown label."""
    text = str(value).replace("\r", " ").replace("\n", " ").replace("\\", "\\\\")
    for marker in ("`", "*", "_", "[", "]"):
        text = text.replace(marker, f"\\{marker}")
    return html.escape(text, quote=True)


def _reason_chip(decision: Any, run: TriageState | None = None) -> str:
    """One line saying why this item is in front of an officer.

    Covers all three escalation causes from ``BUILD.md`` S5.9. The threshold case
    shows both numbers, because "low confidence" without the comparison does not
    tell a reviewer whether the item was marginal or hopeless.
    """
    if run is not None and run.in_human_queue and run.queue_reason is not None:
        return run.queue_reason.replace("_", " ")
    if decision.reason is None:
        return ""
    if decision.reason.value == "low_confidence":
        return f"low confidence {decision.confidence:.2f} < {decision.threshold:.2f}"
    return f"bucket requires review â€” {decision.reason.value.replace('_', ' ')}"


def _short_reason(decision: Any, run: TriageState | None = None) -> str:
    """The reason chip, abbreviated to fit one queue row.

    The full sentence from :func:`_reason_chip` is what the detail pane shows; a
    row has one line, so the threshold case keeps both numbers -- which is the part
    that tells a reviewer whether the item was marginal -- and the structural cases
    drop the "bucket requires review" preamble, since sitting in the review queue
    already says that. The vocabulary stays closed either way, so the queue can
    still be grouped by it.
    """
    if run is not None and run.in_human_queue and run.queue_reason is not None:
        return run.queue_reason.replace("_", " ")
    if decision.reason is None:
        return ""
    if decision.reason.value == "low_confidence":
        # A plain "<": the label is markdown, not HTML, so an escaped entity would
        # render literally.
        return f"{decision.confidence:.2f} < {decision.threshold:.2f}"
    return decision.reason.value.replace("_", " ")


def _queue_row(
    row: dict[str, Any],
    decision: Any,
    run: TriageState | None,
    *,
    key_prefix: str,
) -> None:
    """One compact list row: subject, sender, timestamp and a status chip.

    The row is styled through its widget KEY: Streamlit stamps ``st-key-<key>`` on
    the element container, so a ``qrow-`` prefix gives the CSS above a stable hook,
    and a ``qrow-sel-`` prefix marks the open item -- which is what gives the list a
    visible selected state instead of leaving selection invisible in
    ``session_state``.

    Two lines in one label: the subject, then the routing outcome, any flags, the
    sender and the date. The outcome is coloured with Streamlit's ``:orange[...]``
    markdown rather than HTML, because a button label escapes raw markup.
    """
    selected = st.session_state.get("selected") == row["id"]
    key = f"qrow-{'sel-' if selected else ''}{key_prefix}{row['id']}"

    # Colour is carried by Streamlit's own markdown colour spans, which survive
    # inside a button label where raw HTML does not. Orange for escalation, green
    # for an auto-reply, violet for a redirect -- so the queue reads down its
    # status column without the officer parsing each line.
    if _in_human_queue(decision, run):
        chip_text = f":orange[{_short_reason(decision, run)}]"
    elif decision.action is Action.REDIRECT:
        chip_text = f":violet[redirect Â· {decision.confidence:.2f}]"
    else:
        chip_text = f":green[auto-reply Â· {decision.confidence:.2f}]"

    # The whole row is ONE button, subject and status in a single markdown label.
    # Drawing the status as a separate element above the button was tried first and
    # collides: Streamlit's inter-widget spacing cannot be negated reliably enough
    # to stack two elements into one visual row, and the chip landed on top of the
    # subject. Keeping it in the label also makes the entire row the click target.
    flag_text = "".join(f" Â· :red[{f.value.replace('_', ' ')}]" for f in row["flags"])
    subject = _markdown_inline(row["subject"])
    sender = _markdown_inline(row["sender"])
    stamp = row["received_at"].strftime("%d %b")

    if st.button(
        f"**{subject}**  \n{chip_text}{flag_text} Â· {sender} Â· {stamp}",
        key=key, use_container_width=True,
    ):
        st.session_state["selected"] = row["id"]
        st.rerun()


# --------------------------------------------------------------------------- #
# Sidebar
# --------------------------------------------------------------------------- #

st.sidebar.title("Controls")
split_name = st.sidebar.selectbox("Split", ["test", "calibration", "train"], index=0)
limit = st.sidebar.slider("Emails to load", 20, 200, 60, step=20)
multiplier = st.sidebar.slider(
    "Threshold multiplier", 0.2, 2.0, 1.0, step=0.05,
    help="Scales every per-bucket threshold. 1.0 is the configured operating point.",
)
drafting_on = st.sidebar.toggle(
    "Draft live", value=False,
    help="Calls the drafting model for the selected item. Free-tier rate limits are "
         "visible rather than hidden.",
)

thresholds = load_thresholds()
scaler = TemperatureScaler.load()
if not scaler.fitted:
    st.sidebar.warning("Calibration is not fitted â€” confidences are raw.")

st.sidebar.caption(
    f"temperature {scaler.temperature:.4f} Â· "
    f"auto_answerable threshold {thresholds.get('auto_answerable', 0.5) * multiplier:.2f}"
)


# --------------------------------------------------------------------------- #
# Route at the current multiplier
# --------------------------------------------------------------------------- #

try:
    rows = _triage(split_name, limit)
except ModelNotTrainedError as exc:
    st.error(f"The classifier is not trained yet.\n\n{exc}")
    st.caption(
        "Everything else in the pipeline is wired and will run as soon as the "
        "artefact exists â€” scrubbing, rollup, calibration, routing and the SOP pane "
        "all read from it."
    )
    st.stop()
except Exception as exc:  # noqa: BLE001 -- a broken pipeline is a message, not a stack
    st.error(f"Triage failed: {type(exc).__name__}: {exc}")
    st.exception(exc)
    st.stop()

index = _index()
decisions = [
    route(
        row["score"], index.sops_for(row["predicted"]), row["flags"],
        dict(thresholds), calibrated=scaler.fitted, multiplier=multiplier,
    )
    for row in rows
]

runs = _draft_runs()
queued = [
    (row, decision, runs.get(_draft_run_key(split_name, row["id"], multiplier)))
    for row, decision in zip(rows, decisions, strict=True)
]
automated = [item for item in queued if not _in_human_queue(item[1], item[2])]
escalated = [item for item in queued if _in_human_queue(item[1], item[2])]
routing_automated = sum(decision.is_automated for decision in decisions)
auto_reply_routes = sum(decision.action is Action.AUTO_REPLY for decision in decisions)
redirect_routes = sum(decision.action is Action.REDIRECT for decision in decisions)

st.title("Citizen correspondence â€” officer queue")
coverage_col, reply_col, redirect_col, review_col = st.columns(4)
coverage_col.metric(
    "Routing coverage",
    f"{routing_automated / max(len(rows), 1):.1%}",
    help="Share the router chose to automate. Draft failures do not alter this safety metric.",
)
reply_col.metric("Auto-reply routes", auto_reply_routes)
redirect_col.metric("Redirect routes", redirect_routes)
review_col.metric("Needs review", len(escalated))


# --------------------------------------------------------------------------- #
# The two queues
# --------------------------------------------------------------------------- #

#: Queue-to-detail proportions. The queue needs enough width for a subject line to
#: survive without truncating, and the detail pane carries the SOP in full, so it
#: takes the larger share -- but not by as much as the earlier 1:1.4, which left the
#: list cramped while the detail pane sat half empty.
queue_col, detail_col = st.columns([1, 1.15], gap="medium")

with queue_col:
    auto_tab, review_tab = st.tabs(
        [f"Automation ({len(automated)})", f"Needs review ({len(escalated)})"]
    )

    with auto_tab:
        if not automated:
            st.caption("Nothing was automated at this threshold.")
        for row, decision, run in automated:
            _queue_row(row, decision, run, key_prefix="a")

    with review_tab:
        if not escalated:
            st.caption("Nothing escalated at this threshold.")
        for row, decision, run in escalated:
            _queue_row(row, decision, run, key_prefix="e")


# --------------------------------------------------------------------------- #
# Detail pane
# --------------------------------------------------------------------------- #

with detail_col:
    selected_id = st.session_state.get("selected")
    pair = next(
        ((r, d, run) for r, d, run in queued if r["id"] == selected_id),
        None,
    )

    if pair is None:
        st.info("Select an item from either queue.")
    else:
        row, decision, draft_run = pair
        safe_subject = html.escape(str(row["subject"]), quote=True)
        safe_sender = html.escape(str(row["sender"]), quote=True)
        st.markdown(
            f"<div style='font-size:1.35rem;font-weight:650;line-height:1.3;"
            f"margin-bottom:2px'>{safe_subject}</div>"
            f"<div style='font-size:0.8rem;opacity:0.65;margin-bottom:10px'>"
            f"{safe_sender} Â· {row['received_at'].strftime('%d %b %Y, %H:%M')}</div>",
            unsafe_allow_html=True,
        )

        if _in_human_queue(decision, draft_run):
            st.warning(_reason_chip(decision, draft_run), icon="âš ï¸")
        else:
            st.success(f"{decision.action.value} Â· confidence {decision.confidence:.2f}")

        a, b, c = st.columns(3)
        a.caption(f"**Predicted**\n\n{row['predicted']}")
        b.caption(f"**Bucket**\n\n{decision.bucket.value}")
        c.caption(f"**Flags**\n\n{', '.join(f.value for f in row['flags']) or 'â€”'}")

        st.text_area("Email (scrubbed)", row["body"], height=180, disabled=True)
        st.caption(
            "Shown scrubbed, because this is exactly what the classifier and any "
            "external call saw. Real values never leave the machine."
        )

        # --- drafting -------------------------------------------------------
        if decision.is_automated:
            draft_key = _draft_run_key(split_name, row["id"], multiplier)
            if draft_run is None and drafting_on:
                with st.spinner("Drafting â€¦"):
                    try:
                        draft_run = run_one(
                            _graph(multiplier),
                            TriageState(email=_email_for(split_name, row["id"])),
                        )
                        runs[draft_key] = draft_run
                    except Exception as exc:  # noqa: BLE001
                        draft_run = None
                        st.error(f"Drafting failed: {exc}")

                if draft_run is not None and draft_run.in_human_queue:
                    st.rerun()

            draft = draft_run.draft if draft_run is not None else None
            if draft is not None:
                if draft.status is DraftStatus.OK:
                    st.markdown("**Draft reply**")
                    st.info(draft.text)
                    st.caption(f"Grounded on {', '.join(draft.grounded_on) or 'â€”'}")
                elif draft.status is DraftStatus.FAILED:
                    reason = (
                        draft.failure_reason.value if draft.failure_reason else "unknown"
                    ).replace("_", " ")
                    st.error(f"draft failed: {reason}")
                    st.caption(
                        "The item still carries its SOP below, so the officer can "
                        "write the reply from the same source the drafter would have used."
                    )
                    if st.button("Retry draft", key=f"retry-{draft_key}"):
                        runs.pop(draft_key, None)
                        st.rerun()
                else:
                    st.caption("Drafting was not attempted for this routing decision.")
            elif not drafting_on:
                st.caption("Enable **Draft live** in the sidebar to generate a reply.")

        # --- SOP pane -------------------------------------------------------
        st.divider()
        if not row["sop_ids"]:
            st.error(
                "No supporting SOP â€” this class has no indexed procedure, so there is "
                "nothing to ground a reply on. The item escalates by derivation."
            )
        else:
            st.markdown(f"**Procedure â€” {', '.join(row['sop_ids'])}**")
            for sop_id in row["sop_ids"]:
                sop = index.by_id.get(sop_id)
                if sop is None:
                    continue
                with st.expander(f"{sop.sop_id} â€” {sop.title}", expanded=len(row["sop_ids"]) == 1):
                    st.markdown(sop.body)


# --------------------------------------------------------------------------- #
# Risk-coverage
# --------------------------------------------------------------------------- #

st.divider()
curve = _risk_coverage()
if curve is None:
    st.caption("Run `python eval/run_eval.py` to produce the risk-coverage curve.")
else:
    st.subheader("Risk vs coverage")
    st.caption(
        "Swept with the real router over a global threshold multiplier. Reported per "
        "topic rather than as one inbox figure: an aggregate would need a class volume "
        "mix that is unpublished and seasonal."
    )
    try:
        import pandas as pd

        frame = (
            pd.DataFrame(curve["overall"])[["coverage", "risk"]]
            .groupby("coverage", as_index=True)
            .mean()
            .sort_index()
        )
        st.line_chart(frame)
        point = min(
            curve["overall"], key=lambda p: abs(p["multiplier"] - multiplier)
        )
        st.caption(
            f"At multiplier {point['multiplier']:.2f} â€” coverage {point['coverage']:.1%}, "
            f"risk {point['risk']:.1%} over {point['n']} emails. "
            f"AURC {curve.get('aurc_overall')}"
        )
    except ImportError:
        st.caption("pandas is needed for the chart.")
[build-system]
requires = ["setuptools>=68"]
build-backend = "setuptools.build_meta"

[project]
name = "citizen-triage-agent"
version = "0.1.0"
description = "Calibrated triage agent for citizen correspondence"
requires-python = ">=3.11"
dependencies = [
    "pydantic>=2.6",
    "pyyaml>=6.0",
    "torch>=2.2",
    "transformers>=5.0",
    "numpy>=2.0,<2.5",
    "langgraph>=1.0",
    "scikit-learn>=1.4",
    "pandas>=3.0",
    "matplotlib>=3.8",
    "streamlit>=1.33",
    "google-generativeai>=0.8",
    "groq>=0.11",
    "openai>=3.0",
]

[project.optional-dependencies]
dev = [
    "pytest>=8.0",
    "ruff>=0.4",
    "mypy>=2.0",
    "types-PyYAML>=6.0",
    "jupyter>=1.0",
    "ipykernel>=6.29",
]

[tool.setuptools.packages.find]
where = ["src"]

[tool.pytest.ini_options]
testpaths = ["tests"]
pythonpath = ["src"]
addopts = "-q"

[tool.ruff]
line-length = 100
src = ["src", "tests", "scripts", "eval"]

[tool.ruff.lint]
select = ["E", "F", "I", "N", "UP", "B", "SIM"]

[tool.mypy]
python_version = "3.11"
packages = ["triage"]
mypy_path = "src"
strict = true

  README.md:14:
  README.md:15:An agency inbox is not one problem. It is a mixture of questions that a published
> README.md:16:FAQ already answers, questions that require reading a specific taxpayer's record,
  README.md:17:and questions where a wrong answer causes real harm — a citizen mid-fraud, or one
  README.md:18:who cannot pay.
  README.md:19:
  README.md:20:The naive framing is "use an LLM to answer citizen emails". That framing fails on
  README.md:26:that answers 100% of emails at 15% error is unusable in a public-sector context; one
  README.md:27:that answers 35% at 9% error, and hands the rest to a human *with a reason attached*,
> README.md:28:is deployable. This project is built around producing and defending that curve.
  README.md:29:
  README.md:30:This is Annex A sketch 12 (triage agent for citizen emails), taken deliberately at
  README.md:31:its hardest reading: **calibrated confidence and clean human escalation**, not
  README.md:32:autocomplete for officers.
  README.md:98:**Retrieval is a dictionary lookup.** 17 SOPs, ~100 KB. A vector store would buy
  README.md:99:nothing and would put a similarity threshold immediately upstream of the escalation
> README.md:100:decision. `CLASS_TO_SOPS` is built at startup by inverting the `intents:` line each
  README.md:101:SOP declares — so routing policy lives in the corpus, not in code.
  README.md:102:
  README.md:103:---
  README.md:104:
  README.md:109:| Source | Use | Licensing / privacy |
  README.md:110:|---|---|---|
> README.md:111:| IRAS individual-income-tax guidance pages | Factual reference for authoring SOPs | Read as 
reference; fetched to a gitignored scratch dir, **not redistributed**. Only restatements-with-citations are committed. 
|
  README.md:112:| CFPB Consumer Complaints (Hugging Face) | Register/style exemplars only | Public dataset; PII 
pre-redacted by the publisher. No text copied into the corpus. |
  README.md:113:| Author-written SOP + scenario specifications | Corpus and email generation | Original work. |
  README.md:114:
  README.md:115:**The SOP corpus is authored, not scraped.** No agency publishes its internal SOPs,
  README.md:117:synthetic officer-facing procedure whose every factual claim traces to a public IRAS
  README.md:118:URL recorded in its frontmatter — validated at startup, and `scripts/generate_sops.py
> README.md:119:--check` fails the build if a citation does not resolve. Every file carries a banner
  README.md:120:marking it synthetic. None reflects internal IRAS material, template, or practice.
  README.md:121:
  README.md:122:**Licensing position.** Copyright protects expression, not facts: tax rates,
  README.md:123:deadlines and relief caps are facts stated in legislation. Pages were read as
  README.md:128:3,000 emails from **116 authored scenarios**, generated by GPT-4o. Real citizen
  README.md:129:correspondence cannot ethically be used, and no public corpus of Singapore government
> README.md:130:email enquiries exists.
  README.md:131:
  README.md:132:The generation is structured to avoid the failure mode that makes synthetic data
  README.md:133:worthless — a model learning the generator's tells rather than the intent:
  README.md:134:
  README.md:195:
  README.md:196:**5.5 LLM-as-judge — declared incomplete.** A Groq-hosted judge scores draft
> README.md:197:groundedness, deliberately a different model family from the drafter. BUILD.md commits
  README.md:198:to reporting judge–human agreement, because agreement is what makes an LLM judge
  README.md:199:defensible rather than decorative. **That agreement figure has not been computed, so
  README.md:200:no groundedness number is claimed here.** See §8.
  README.md:201:
  README.md:304:## 7. Setup and execution
  README.md:305:
> README.md:306:Requires Python 3.11+. Verified on Windows 11 / Python 3.14. A reproducible,
  README.md:307:CPU-only Docker image is included for clean-machine runs.
  README.md:308:
  README.md:309:```bash
  README.md:310:git clone https://github.com/<USER>/bojji.git && cd bojji
  README.md:311:python -m venv .venv && source .venv/bin/activate   # Windows: .venv\Scripts\activate
> README.md:312:pip install -r requirements.txt
  README.md:313:
  README.md:314:cp .env.example .env          # add GEMINI_API_KEY for drafting (free tier)
  README.md:315:
  README.md:316:python -m pytest              # 387 tests
  README.md:317:python eval/run_eval.py       # regenerates eval/results/
> README.md:318:streamlit run app/streamlit_app.py
  README.md:319:```
  README.md:320:
  README.md:321:Or run the same demo in Docker:
  README.md:322:
  README.md:323:```bash
> README.md:324:docker build -t citizen-triage-agent .
  README.md:325:docker run --rm -p 8501:8501 --env-file .env citizen-triage-agent
  README.md:326:```
  README.md:327:
  README.md:328:**The pipeline runs with no API key at all.** Classification, calibration, retrieval
  README.md:343:- **The judge–human agreement figure is not computed**, so no groundedness number is
  README.md:344:  claimed. `eval/results/drafting.json` reads `{"skipped": true}`. Drafting availability
> README.md:345:  and grounding accuracy require Gemini quota this build ran out of.
  README.md:346:- **Calibration is currently a near-no-op** (T=0.998). See §6.4.
  README.md:347:- **Scam detection is the weakest guarantee.** The lexical flag has precision 1.000
  README.md:348:  (zero false positives on all 3,000 emails), but recall is **0.827 corpus-wide** —
  README.md:349:  not the 0.952 the test split alone reports. The 52 misses describe the *event*
  README.md:366:
  README.md:367:**Target user and environment.** The user is a correspondence officer, not a citizen:
> README.md:368:the interface is a two-queue review screen, and the output is a routing decision plus
  README.md:369:a draft an officer approves. It sits inside an agency network — classifier on
  README.md:370:on-premise CPU, only scrubbed text crossing the boundary to a drafting API.
  README.md:371:
  README.md:372:**Compute footprint at scale.** The classifier is 88 MB at ~0.67 s/email on one CPU
  README.md:393:## 10. Development narrative
  README.md:394:
> README.md:395:The build log with full decision history is `<SCRATCHPAD>/BUILD.md`. In brief:
  README.md:396:
  README.md:397:**What changed along the way.** The taxonomy was **reshaped from 12 classes to 10**
> README.md:398:mid-build: `oos_business_tax` and `oos_other_agency` were merged (they shared a bucket
  README.md:399:*and* an action, so the split bought nothing downstream, and the classifier could not
  README.md:400:separate them — one scored F1 0.000 with half its errors landing on its sibling), and
  README.md:401:`account_specific` was **demoted from a class to a flag**. That second change is the
> README.md:402:more interesting one: being about your own record is a property an enquiry *has*, not
  README.md:403:a topic it is *about* — "how do instalments work" and "what is the status of my
  README.md:404:instalment plan" differ by one possessive. Topical vocabulary dominated the one or two
  README.md:405:tokens carrying the actual signal, so as a class it failed; as a lexical flag consulted
  README.md:406:before any confidence, it works.
  README.md:421:
  README.md:422:**Things that broke and what they taught.** Two free-tier models were *withdrawn*
> README.md:423:mid-build — Groq's `llama-3.3-70b` and Gemini's `gemini-2.0-flash`, both returning 404.
  README.md:424:They failed differently, and that contrast shaped the design: the Groq withdrawal was
> README.md:425:silent (dropped samples fell back to a uniform distribution, so numbers were quietly
  README.md:426:wrong), while the Gemini one was loud (drafting has an explicit failure path, so items
  README.md:427:escalated with their SOPs and the error was recorded on the state). That is why the
  README.md:428:model identifier is stamped into every result file and why the drafter has **no
  README.md:429:template fallback** that would mask an outage.
  README.md:432:DistilBERT on deployment size. Gemini for drafting and Groq for judging, chosen from
  README.md:433:different families so no model is scored on its own output. GPT-4o for generation
> README.md:434:only — build-time and paid, with its output frozen and committed so no grader re-runs
  README.md:435:a paid step.
  README.md:436:
  README.md:437:---
  README.md:438:
  README.md:439:## 11. Coding agent usage
  README.md:440:
> README.md:441:This project was built with **Claude Code** (Claude Opus) as a pair-programming and
  README.md:442:audit partner, used in three distinct modes:
  README.md:443:
  README.md:444:1. **Implementation.** Most module code and tests were drafted with the agent against
> README.md:445:   a design I specified in `BUILD.md`, then reviewed and corrected by me.
  README.md:446:2. **Adversarial audit.** The agent was asked to attack its own output — probing
  README.md:447:   invariants exhaustively rather than reading them. This is where the highest-value
  README.md:448:   findings came from, each reproduced at the command line before being fixed:
  README.md:449:
  README.md:465:   the command line before being written down.
  README.md:466:
> README.md:467:Where the agent and I disagreed, the disagreement is recorded in `BUILD.md` rather than
  README.md:468:silently resolved — including one case where I asked it to broaden PII detection and
  README.md:469:the measurement showed the change would damage classifier input for no real gain.
  README.md:470:
  README.md:471:**Session logs** are in `AI assistant logs/`.
  README.md:483:  more than doubling the variants of the existing ones, and would widen the calibration
  README.md:484:  split — currently the binding constraint on the temperature fit.
> README.md:485:- Real anonymised enquiries as a validation-only slice, to test whether the synthetic
  README.md:486:  situation set resembles the real distribution — the one thing this project cannot
  README.md:487:  currently check about itself.
  README.md:488:- Learning from officer corrections: scheduled threshold recalibration and
  README.md:489:  calibration-drift monitoring.

